def start_trials(apps, schema_editor):
    """Organizations set up before ERP billing get the free trial from now
    (billing.erp.start_trial)."""
    Company = apps.get_model('accounts', 'Company')
    Subscription = apps.get_model('billing', 'OrganizationSubscription')
    ends = timezone.now() + timedelta(days=getattr(settings, 'ERP_TRIAL_DAYS', 14))
    for company in Company.objects.exclude(erp_plan='').filter(erp_subscription__isnull=True):
        Subscription.objects.create(company=company, plan=company.erp_plan, status='trialing', trial_ends_at=ends)


